     1	/**
     2	 * Evaluate an `If-None-Match` field-value against an ETag using the weak
     3	 * comparison function (RFC 9110 §8.8.3.2 and §13.1.2).
     4	 *
     5	 * - `*` matches any current representation.
     6	 * - The field-value is a comma-separated list of entity-tags. An opaque-tag is
     7	 *   a quoted string whose value may itself contain commas, so tags are matched
     8	 *   by their quoted boundaries rather than by naive comma splitting.
     9	 * - Weak comparison ignores the `W/` weakness indicator on either side.
    10	 */
    11	export function matchETag(ifNoneMatch: string, etag: string): boolean {
    12	  if (ifNoneMatch.trim() === "*") {
    13	    return true;
    14	  }
    15	  const target = opaqueTag(etag);
    16	  return splitETags(ifNoneMatch).some((tag) => opaqueTag(tag.trim()) === target);
    17	}
    18	
    19	/**
    20	 * Evaluate an incoming conditional request against the current representation's
    21	 * validators, returning `true` when it matches and a `304 Not Modified` should
    22	 * be sent.
    23	 *
    24	 * RFC 9110 §13.1.3: a recipient MUST ignore `If-Modified-Since` when the request
    25	 * contains an `If-None-Match` header field. `If-None-Match` takes precedence;
    26	 * `If-Modified-Since` is only evaluated when it is absent. A present-but-empty
    27	 * `If-None-Match` is malformed and treated as absent.
    28	 */
    29	export function isCacheMatch(
    30	  headers: Headers,
    31	  validators: {
    32	    etag?: string;
    33	    lastModified?: Date;
    34	    /** Overrides the request header, for a caller holding the original value. */
    35	    ifNoneMatch?: string;
    36	    /** Overrides the request header, for a caller holding the original value. */
    37	    ifModifiedSince?: string;
    38	  },
    39	): boolean {
    40	  const ifNoneMatch = validators.ifNoneMatch ?? headers.get("if-none-match");
    41	  if (ifNoneMatch) {
    42	    return !!validators.etag && matchETag(ifNoneMatch, validators.etag);
    43	  }
    44	  if (validators.lastModified) {
    45	    const ifModifiedSince = validators.ifModifiedSince ?? headers.get("if-modified-since");
    46	    return !!ifModifiedSince && new Date(ifModifiedSince) >= validators.lastModified;
    47	  }
    48	  return false;
    49	}
    50	
    51	function opaqueTag(tag: string): string {
    52	  return tag.startsWith("W/") ? tag.slice(2) : tag;
    53	}
    54	
    55	/**
